ValidationRule.errorConditionFormula:
AND(
    NOT(ISNEW()),
    OR(
        PRIORVALUE(Project_Stage__c) = "Closed Lost",
        PRIORVALUE(Project_Stage__c) = "Closed Won"
    ),
    NOT(
        OR(
            $Profile.Name = "System Administrator",
            $Profile.Name = "Utkarsh Admin"
        )
    )
)
